/* ─────────────────────────────────────────────
   MARQUEE SECTION
───────────────────────────────────────────── */
const techStack = [
  "Spring Boot", "Java 21", "REST APIs", "JWT Auth", "MySQL",
  "JPA / Hibernate", "Git & GitHub", "React", "Maven", "Groq API",
  "OOP Design", "Multithreading", "Collections", "DSA", "MVC Pattern",
  "JDBC", "Servlets", "JSP", "OpenStreetMap", "LeetCode 320+",
];

const MarqueeSection = () => {
  const ref = useRef(null);
  const [offset, setOffset] = useState(200);
  useEffect(() => {
    const handler = () => {
      if (!ref.current) return;
      const top = ref.current.getBoundingClientRect().top + window.scrollY;
      const val = (window.scrollY - top + window.innerHeight) * 0.3;
      setOffset(val);
    };
    window.addEventListener("scroll", handler, { passive: true });
    return () => window.removeEventListener("scroll", handler);
  }, []);
  const row1 = [...techStack, ...techStack, ...techStack];
  const row2 = [...techStack.slice(10), ...techStack.slice(10), ...techStack.slice(10)];
  const Badge = ({ text }) => (
    <div style={{
      flexShrink: 0,
      padding: "14px 28px",
      borderRadius: "9999px",
      border: "1px solid #2a2a3a",
      background: "#111",
      color: "#D7E2EA",
      fontSize: "clamp(0.75rem, 1.1vw, 1rem)",
      fontWeight: 500,
      textTransform: "uppercase",
      letterSpacing: "0.1em",
      whiteSpace: "nowrap",
      transition: "border-color 0.2s, background 0.2s",
    }}>{text}</div>
  );
  return (
    <section ref={ref} style={{ background: "#0C0C0C", padding: "80px 0 40px", overflow: "hidden" }}>
      {["row1", "row2"].map((rowKey, ri) => (
        <div key={rowKey} style={{ marginBottom: ri === 0 ? 12 : 0 }}>
          <div style={{
            display: "flex", gap: 12,
            transform: `translateX(${ri === 0 ? offset - 200 : -(offset - 200)}px)`,
            willChange: "transform", transition: "none",
          }}>
            {(ri === 0 ? row1 : row2).map((t, i) => <Badge key={i} text={t} />)}
          </div>
        </div>
      ))}
    </section>
  );
};

